const root=process.cwd(),config=JSON.parse(await readFile(resolve(root,'site.json'),'utf8')),content=JSON.parse(await readFile(resolve(root,'content.json'),'utf8'));
const production=process.env.BUILD_TARGET==='production',base=new URL(process.env.SITE_URL??`https://${config.domain}/`);if(!base.pathname.endsWith('/'))base.pathname+='/';
if(production&&(!process.env.SITE_URL||base.protocol!=='https:'))throw Error('Build produkcyjny wymaga rzeczywistego SITE_URL z HTTPS.');
const indexable=production&&process.env.INDEXABLE==='true';
const analytics=production&&base.hostname===config.domain?process.env.CF_WEB_ANALYTICS_TOKEN:'';
