const redirects={'/wiedza/co-to-jest-oki/':'/podstawy/co-to-jest-oki/','/wiedza/limity-i-srednie/':'/podatek/limity-i-zwolnienia/','/wiedza/jak-wybrac-operatora/':'/wybor/jak-wybrac-operatora/','/wiedza/pierwszy-plan/':'/plany/pierwsze-oki/','/kalkulatory/kilka-kont-oki/':'/kalkulatory/podatek-oki/'};
for(const [from,to] of Object.entries(redirects)){const folder=resolve(dist,'.'+from);await mkdir(folder,{recursive:true});await writeFile(resolve(folder,'index.html'),`<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta http-equiv="refresh" content="0;url=${rel(from)+to.slice(1)}"><link rel="canonical" href="${h(url(to))}"><meta name="description" content="Nowy adres treści"><title>Nowy adres | ${config.name}</title></head><body><h1>Ta treść ma nowy adres</h1><a href="${rel(from)+to.slice(1)}">Przejdź do właściwej strony</a></body></html>`);}
await writeFile(resolve(dist,'assets/favicon.svg'),`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48"><rect width="48" height="48" rx="12" fill="${accents[config.id]}"/><circle cx="24" cy="24" r="11" fill="none" stroke="white" stroke-width="6"/></svg>`);
await writeFile(resolve(dist,'404.html'),`<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta name="description" content="Nie znaleziono strony. Wróć do katalogu kalkulatorów i poradników."><link rel="canonical" href="${base.href}"><title>Nie znaleziono strony | ${config.name}</title></head><body style="font:20px/1.6 system-ui;max-width:720px;margin:10vh auto;padding:24px"><h1>Nie znaleziono tej strony</h1><p>Wybierz pytanie w katalogu narzędzi albo wróć do bazy wiedzy.</p><p><a href="${url('/kalkulatory/')}">Kalkulatory</a> · <a href="${url('/wiedza/')}">Wiedza</a> · <a href="${base.href}">Strona główna</a></p></body></html>`);
await writeFile(resolve(dist,'robots.txt'),indexable?`User-agent: *\nAllow: /\nSitemap: ${url('/sitemap.xml')}\n`:'User-agent: *\nDisallow: /\n');
await writeFile(resolve(dist,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${paths.map(p=>`<url><loc>${h(url(p))}</loc><lastmod>2026-11-08</lastmod></url>`).join('')}</urlset>`);
await writeFile(resolve(dist,'reguly.json'),JSON.stringify({...methodology(),calculatorCount:calculators.length,articleCount:content.length},null,2));
await writeFile(resolve(dist,'.nojekyll'),'');
if(production&&base.hostname===config.domain&&base.pathname==='/')await writeFile(resolve(dist,'CNAME'),config.domain+'\n');
await writeFile(resolve(dist,'build.json'),JSON.stringify({brand:config.id,engineVersion:methodology().calculationVersion,baseUrl:base.href,indexable,mode:production?'production':'local',pageCount:paths.length,calculators:calculators.length,articles:content.length,analyticsEnabled:!!analytics},null,2));
console.log(`Zbudowano ${config.name}: ${paths.length} stron, ${calculators.length} kalkulatorów, ${content.length} poradników (${production?'produkcja':'lokalnie'}).`);
